SELECT MIN(UnitPrice) AS MinPrice,
       MAX(UnitPrice) AS MaxPrice
FROM Products;

SELECT ProductName, UnitPrice
FROM Products
WHERE UnitPrice > (
    SELECT AVG(UnitPrice)
    FROM Products
);

SELECT ProductName,
       UnitPrice * UnitsInStock AS TotalValue
FROM Products;

SELECT c.CompanyName, o.OrderDate
FROM Customers c
INNER JOIN Orders o ON c.CustomerID = o.CustomerID;

SELECT Customers.CompanyName, Orders.OrderDate
FROM Customers
INNER JOIN Orders ON Customers.CustomerID = Orders.CustomerID;

SELECT p.ProductName, od.Quantity
FROM [Order Details] od
INNER JOIN Products p ON od.ProductID = p.ProductID;

CREATE PROCEDURE GetAllProducts
AS
BEGIN
    SET NOCOUNT ON;

    SELECT ProductName, UnitPrice, UnitsInStock
    FROM Products;
END;
GO

CREATE PROCEDURE GetOrdersByCustomer
    @CustomerID NVARCHAR(5)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT OrderID, OrderDate, Freight
    FROM Orders
    WHERE CustomerID = @CustomerID;
END;
GO

CREATE PROCEDURE GetProductsByCategory
    @CategoryID INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT ProductName, UnitPrice
    FROM Products
    WHERE CategoryID = @CategoryID;
END;
GO

CREATE PROCEDURE UpdateProductPrice
    @ProductID INT,
    @NewPrice MONEY
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE Products
    SET UnitPrice = @NewPrice
    WHERE ProductID = @ProductID;
END;
GO

CREATE PROCEDURE AddProductAndSell
    @ProductName NVARCHAR(40),
    @SupplierID INT,
    @CategoryID INT,
    @UnitPrice MONEY,
    @UnitsInStock SMALLINT,
    @Quantity SMALLINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ProductID INT;

    -- Insert new product
    INSERT INTO Products (ProductName, SupplierID, CategoryID, UnitPrice, UnitsInStock)
    VALUES (@ProductName, @SupplierID, @CategoryID, @UnitPrice, @UnitsInStock);

    -- Get the new ProductID
    SET @ProductID = SCOPE_IDENTITY();

    -- Insert into Order Details for OrderID 11012
    INSERT INTO [Order Details] (OrderID, ProductID, UnitPrice, Quantity)
    VALUES (11012, @ProductID, @UnitPrice, @Quantity);

    -- Show the inserted record
    SELECT *
    FROM [Order Details]
    WHERE OrderID = 11012 AND ProductID = @ProductID;
END;
GO
